PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX envthes: <http://vocabs.lter-europe.net/EnvThes/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX schema: <http://schema.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?catchment ?catchmentName
WHERE {
  GRAPH <hydroturtle/quadica> {
    {
      SELECT ?targetCatchment (AVG(?middleValue) AS ?annualMedian)
      WHERE {
        {
          SELECT ?targetCatchment ?middleValue
                 (COUNT(DISTINCT ?allObs) AS ?totalCount)
                 (COUNT(DISTINCT ?lessObs) AS ?lessCount)
                 (COUNT(DISTINCT ?greaterObs) AS ?greaterCount)
          WHERE {
            ?middleObs a sosa:Observation ;
              sosa:hasFeatureOfInterest ?targetCatchment ;
              (hyobs:hasAnalyte|sosa:observedProperty) ?middleAnalyte ;
              sosa:resultTime ?middleTime ;
              sosa:hasResult ?middleResult .
            ?middleResult qudt:numericValue ?middleRaw .
            OPTIONAL { ?middleAnalyte schema:name ?middleAnalyteName . }
            BIND(CONCAT(STR(?middleAnalyte), " ", COALESCE(STR(?middleAnalyteName), "")) AS ?middleAnalyteText)
            BIND(xsd:double(?middleRaw) AS ?middleValue)
            FILTER(STRSTARTS(STR(?middleTime), "1999"))
            FILTER(REGEX(?middleAnalyteText, "NO[₃3].?N", "i"))

            ?allObs a sosa:Observation ;
              sosa:hasFeatureOfInterest ?targetCatchment ;
              (hyobs:hasAnalyte|sosa:observedProperty) ?allAnalyte ;
              sosa:resultTime ?allTime ;
              sosa:hasResult ?allResult .
            ?allResult qudt:numericValue ?allRaw .
            OPTIONAL { ?allAnalyte schema:name ?allAnalyteName . }
            BIND(CONCAT(STR(?allAnalyte), " ", COALESCE(STR(?allAnalyteName), "")) AS ?allAnalyteText)
            FILTER(STRSTARTS(STR(?allTime), "1999"))
            FILTER(REGEX(?allAnalyteText, "NO[₃3].?N", "i"))

            OPTIONAL {
              ?lessObs a sosa:Observation ;
                sosa:hasFeatureOfInterest ?targetCatchment ;
                (hyobs:hasAnalyte|sosa:observedProperty) ?lessAnalyte ;
                sosa:resultTime ?lessTime ;
                sosa:hasResult ?lessResult .
              ?lessResult qudt:numericValue ?lessRaw .
              OPTIONAL { ?lessAnalyte schema:name ?lessAnalyteName . }
              BIND(CONCAT(STR(?lessAnalyte), " ", COALESCE(STR(?lessAnalyteName), "")) AS ?lessAnalyteText)
              BIND(xsd:double(?lessRaw) AS ?lessValue)
              FILTER(STRSTARTS(STR(?lessTime), "1999"))
              FILTER(REGEX(?lessAnalyteText, "NO[₃3].?N", "i"))
              FILTER(?lessValue < ?middleValue)
            }

            OPTIONAL {
              ?greaterObs a sosa:Observation ;
                sosa:hasFeatureOfInterest ?targetCatchment ;
                (hyobs:hasAnalyte|sosa:observedProperty) ?greaterAnalyte ;
                sosa:resultTime ?greaterTime ;
                sosa:hasResult ?greaterResult .
              ?greaterResult qudt:numericValue ?greaterRaw .
              OPTIONAL { ?greaterAnalyte schema:name ?greaterAnalyteName . }
              BIND(CONCAT(STR(?greaterAnalyte), " ", COALESCE(STR(?greaterAnalyteName), "")) AS ?greaterAnalyteText)
              BIND(xsd:double(?greaterRaw) AS ?greaterValue)
              FILTER(STRSTARTS(STR(?greaterTime), "1999"))
              FILTER(REGEX(?greaterAnalyteText, "NO[₃3].?N", "i"))
              FILTER(?greaterValue > ?middleValue)
            }
          }
          GROUP BY ?targetCatchment ?middleValue
        }
        FILTER(?lessCount <= (?totalCount / 2) && ?greaterCount <= (?totalCount / 2))
      }
      GROUP BY ?targetCatchment
      ORDER BY DESC(?annualMedian)
      LIMIT 1
    }

    ?targetCatchment geo:hasGeometry/geo:asWKT ?targetWKT .

    ?catchment a envthes:30212 ;
      geo:hasGeometry/geo:asWKT ?catchmentWKT .
    OPTIONAL { ?catchment schema:name ?catchmentName . }

    FILTER(?catchment != ?targetCatchment)
    FILTER(<http://www.opengis.net/def/function/geosparql/sfTouches>(?catchmentWKT, ?targetWKT))
  }
}

